import React from 'react';
import { CStatistic } from '@cloud-materials/common';

const CCountdown = CStatistic.Countdown;

export default () => {
  const now = Date.now();
  return (
    <>
      <CCountdown
        title="天级别"
        value={now + 1000 * 60 * 60 * 2}
        now={now}
        start
        format="D 天 H 时 m 分 s 秒"
        onFinish={() => {
          console.log('倒计时完成');
        }}
        renderFormat={(_valueDiff, formattedDiff) => {
          const day = formattedDiff.split('天')[0];
          const hour = formattedDiff.split('时')[0].split('天')[1];
          const minute = formattedDiff.split('分')[0].split('时')[1];
          const second = formattedDiff.split('秒')[0].split('分')[1];
          return (
            <span>
              {day}
              <span style={{ fontSize: 10, color: '#ccc' }}>天</span>
              {hour}
              <span style={{ fontSize: 10, color: '#ccc' }}>时</span>
              {minute}
              <span style={{ fontSize: 10, color: '#ccc' }}>分</span>
              {second}
              <span style={{ fontSize: 10, color: '#ccc' }}>秒</span>
            </span>
          );
        }}
        style={{ width: 250 }}
      />
      <CCountdown
        title="秒级别"
        value={now + 1000 * 60 * 60}
        now={now}
        start
        format="H:m:s"
        onFinish={() => {
          console.log('倒计时完成');
        }}
        style={{ marginLeft: 16, width: 250 }}
      />
      <CCountdown
        title="时：分 ：秒. 毫秒"
        value={now + 1000 * 60 * 60}
        now={now}
        start
        format="HH:mm:ss.SSS"
        onFinish={() => {
          console.log('倒计时完成');
        }}
        style={{ marginLeft: 16, width: 250 }}
      />
    </>
  );
};

